package com.pousadamareal.api;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.pousadamareal.domain.Room;
import com.pousadamareal.service.DataStore;
import io.javalin.http.Context;

import java.util.Comparator;

public class RoomController {
    private final DataStore dataStore;

    public RoomController(DataStore dataStore) {
        this.dataStore = dataStore;
    }

    public void getRooms(Context ctx) {
        JsonArray rooms = new JsonArray();
        dataStore.getAllRooms().stream()
                .sorted(Comparator.comparingInt(r -> r.number))
                .forEach(room -> {
                    JsonObject obj = new JsonObject();
                    obj.addProperty("number", room.number);
                    obj.addProperty("type", room.type.name());
                    obj.addProperty("capacity", room.capacity);
                    obj.addProperty("nightlyRate", Math.round(room.nightlyRate.doubleValue() * 100.0) / 100.0);
                    rooms.add(obj);
                });

        ctx.json(rooms);
    }
}

