package com.pousadamareal.api;

import com.google.gson.JsonObject;
import com.pousadamareal.domain.Reservation;
import com.pousadamareal.domain.ReservationRequest;
import com.pousadamareal.service.DataStore;
import com.pousadamareal.service.ReservationService;
import io.javalin.http.Context;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

public class ReservationController {
    private final ReservationService reservationService;
    private final DataStore dataStore;
    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ISO_LOCAL_DATE;

    public ReservationController(ReservationService reservationService, DataStore dataStore) {
        this.reservationService = reservationService;
        this.dataStore = dataStore;
    }

    public void createReservation(Context ctx) {
        try {
            JsonObject body = ctx.bodyAsClass(JsonObject.class);

            int roomNumber = getIntField(body, "roomNumber");
            String guestName = getStringField(body, "guestName");
            String guestEmail = getStringField(body, "guestEmail");
            String guestCpf = getStringField(body, "guestCpf");
            String checkInStr = getStringField(body, "checkIn");
            String checkOutStr = getStringField(body, "checkOut");
            int guests = getIntField(body, "guests");
            String ratePlan = getStringField(body, "ratePlan");
            String companyCode = body.has("companyCode") ? body.get("companyCode").getAsString() : null;

            LocalDate checkIn = parseDate(checkInStr);
            LocalDate checkOut = parseDate(checkOutStr);

            ReservationRequest request = new ReservationRequest(
                    roomNumber, guestName, guestEmail, guestCpf,
                    checkIn, checkOut, guests, ratePlan, companyCode
            );

            ReservationService.Result<Reservation> result = reservationService.createReservation(request);

            if (result.success()) {
                ctx.status(201);
                ctx.json(toJson(result.data()));
            } else {
                ctx.status(getStatusCodeForError(result.errorCode()));
                JsonObject error = new JsonObject();
                error.addProperty("error", result.errorCode());
                error.addProperty("message", result.errorMessage());
                ctx.json(error);
            }
        } catch (Exception e) {
            sendBadRequest(ctx, "INVALID_REQUEST", "Invalid request body");
        }
    }

    public void getReservation(Context ctx) {
        long id = Long.parseLong(ctx.pathParam("id"));
        Reservation reservation = dataStore.getReservation(id);

        if (reservation == null) {
            ctx.status(404);
            JsonObject error = new JsonObject();
            error.addProperty("error", "RESERVATION_NOT_FOUND");
            error.addProperty("message", "Reservation not found");
            ctx.json(error);
        } else {
            ctx.json(toJson(reservation));
        }
    }

    public void confirmReservation(Context ctx) {
        try {
            long id = Long.parseLong(ctx.pathParam("id"));
            JsonObject body = ctx.bodyAsClass(JsonObject.class);
            long amountPaid = Math.round(body.get("amountPaid").getAsDouble() * 100);

            ReservationService.Result<Reservation> result = reservationService.confirmReservation(id, amountPaid);

            if (result.success()) {
                ctx.json(toJson(result.data()));
            } else {
                ctx.status(getStatusCodeForError(result.errorCode()));
                JsonObject error = new JsonObject();
                error.addProperty("error", result.errorCode());
                error.addProperty("message", result.errorMessage());
                ctx.json(error);
            }
        } catch (Exception e) {
            sendBadRequest(ctx, "INVALID_REQUEST", "Invalid request body");
        }
    }

    public void cancelReservation(Context ctx) {
        long id = Long.parseLong(ctx.pathParam("id"));
        ReservationService.Result<Reservation> result = reservationService.cancelReservation(id);

        if (result.success()) {
            ctx.json(toJson(result.data()));
        } else {
            ctx.status(getStatusCodeForError(result.errorCode()));
            JsonObject error = new JsonObject();
            error.addProperty("error", result.errorCode());
            error.addProperty("message", result.errorMessage());
            ctx.json(error);
        }
    }

    public void checkIn(Context ctx) {
        long id = Long.parseLong(ctx.pathParam("id"));
        ReservationService.Result<Reservation> result = reservationService.checkIn(id);

        if (result.success()) {
            ctx.json(toJson(result.data()));
        } else {
            ctx.status(getStatusCodeForError(result.errorCode()));
            JsonObject error = new JsonObject();
            error.addProperty("error", result.errorCode());
            error.addProperty("message", result.errorMessage());
            ctx.json(error);
        }
    }

    public void checkOut(Context ctx) {
        long id = Long.parseLong(ctx.pathParam("id"));
        ReservationService.Result<ReservationService.ReservationReceipt> result = reservationService.checkOut(id);

        if (result.success()) {
            ctx.json(receiptToJson(result.data()));
        } else {
            ctx.status(getStatusCodeForError(result.errorCode()));
            JsonObject error = new JsonObject();
            error.addProperty("error", result.errorCode());
            error.addProperty("message", result.errorMessage());
            ctx.json(error);
        }
    }

    public void getReceipt(Context ctx) {
        long id = Long.parseLong(ctx.pathParam("id"));
        ReservationService.Result<ReservationService.ReservationReceipt> result = reservationService.getReceipt(id);

        if (result.success()) {
            ctx.json(receiptToJson(result.data()));
        } else {
            ctx.status(getStatusCodeForError(result.errorCode()));
            JsonObject error = new JsonObject();
            error.addProperty("error", result.errorCode());
            error.addProperty("message", result.errorMessage());
            ctx.json(error);
        }
    }

    private JsonObject toJson(Reservation reservation) {
        JsonObject obj = new JsonObject();
        obj.addProperty("id", reservation.id);
        obj.addProperty("roomNumber", reservation.roomNumber);
        obj.addProperty("guestName", reservation.guestName);
        obj.addProperty("guestEmail", reservation.guestEmail);
        obj.addProperty("guestCpf", reservation.guestCpf);
        obj.addProperty("checkIn", reservation.checkIn.format(ISO_DATE));
        obj.addProperty("checkOut", reservation.checkOut.format(ISO_DATE));
        obj.addProperty("guests", reservation.guests);
        obj.addProperty("ratePlan", reservation.ratePlan);
        obj.addProperty("nights", reservation.nights);
        obj.addProperty("subtotal", reservation.subtotalCents / 100.0);
        obj.addProperty("discount", reservation.discountCents / 100.0);
        obj.addProperty("total", reservation.totalCents / 100.0);
        obj.addProperty("status", reservation.status.name());
        obj.addProperty("amountPaid", reservation.amountPaidCents / 100.0);
        obj.addProperty("refund", reservation.refundCents != null ? reservation.refundCents / 100.0 : null);
        return obj;
    }

    private JsonObject receiptToJson(ReservationService.ReservationReceipt receipt) {
        JsonObject obj = new JsonObject();
        obj.addProperty("title", receipt.title());
        obj.addProperty("reservationId", receipt.reservationId());
        obj.addProperty("guestName", receipt.guestName());
        obj.addProperty("guestCpf", receipt.guestCpf());
        obj.addProperty("roomNumber", receipt.roomNumber());
        obj.addProperty("roomType", receipt.roomType());
        obj.addProperty("checkIn", receipt.checkIn());
        obj.addProperty("checkOut", receipt.checkOut());
        obj.addProperty("nights", receipt.nights());
        obj.addProperty("subtotal", receipt.subtotal() / 100.0);
        obj.addProperty("discount", receipt.discount() / 100.0);
        obj.addProperty("total", receipt.total() / 100.0);
        return obj;
    }

    private int getIntField(JsonObject obj, String field) {
        if (!obj.has(field)) {
            throw new IllegalArgumentException("Missing field: " + field);
        }
        return obj.get(field).getAsInt();
    }

    private String getStringField(JsonObject obj, String field) {
        if (!obj.has(field)) {
            throw new IllegalArgumentException("Missing field: " + field);
        }
        return obj.get(field).getAsString();
    }

    private LocalDate parseDate(String dateStr) {
        try {
            return LocalDate.parse(dateStr, ISO_DATE);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid date format: " + dateStr);
        }
    }

    private int getStatusCodeForError(String errorCode) {
        return switch (errorCode) {
            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
            case "CAPACITY_EXCEEDED" -> 422;
            default -> 400;
        };
    }

    private void sendBadRequest(Context ctx, String code, String message) {
        ctx.status(400);
        JsonObject error = new JsonObject();
        error.addProperty("error", code);
        error.addProperty("message", message);
        ctx.json(error);
    }
}

